server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;

    root /var/www/html;
    index index.html;

    # Detailed benchmark request logging + error logging
    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log  /var/log/nginx/benchmark-error.log warn;

    # Rate limiting: 10 req/s per IP, burst of 10 (zone defined in nginx.conf)
    limit_req zone=benchmark_limit burst=10;

    location / {
        try_files $uri $uri/ =404;
    }

    # Custom 404 page
    error_page 404 /404.html;

    location = /health {
        access_log off;
        return 200 "ok\n";
    }
}
EOF
echo "--- written ---"; cat /etc/nginx/conf.d/benchmark-site.conf

