arguments.command:
cat <<'SCRIPT' > /root/setup-nginx-benchmark.sh
#!/bin/bash
# Setup Nginx benchmark webserver (port 8080, custom logging + rate limiting)
set -e

# --- Install nginx if missing ---
command -v nginx >/dev/null || { apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq nginx; }

# --- Document root + pages ---
mkdir -p /var/www/html
[ -f /var/www/html/index.html ] || printf 'Welcome to the benchmark webserver\n' > /var/www/html/index.html
[ -f /var/www/html/404.html ]   || printf 'Page not found - Please check your URL\n' > /var/www/html/404.html

# --- Custom log format + rate limit zone in nginx.conf (http context) ---
BLOCK=$(mktemp)
cat <<'EOF' > "$BLOCK"

    ##
    # Benchmark Settings (rate limiting + custom log format)
    ##

    # Custom detailed log format: timestamp, method, status, user agent (quoted)
    log_format benchmark '$time_local $request_method $status "$http_user_agent"';

    # Rate limiting zone: 10 requests/sec per client IP, 10MB shared memory
    limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;
EOF
if ! grep -q 'log_format benchmark' /etc/nginx/nginx.conf; then
  awk -v B="$BLOCK" 'BEGIN{while((getline l < B)>0) ins[++n]=l}
    {print; if($0 ~ /^http[ \t]*\{/ && !done){for(i=1;i<=n;i++) print ins[i]; done=1}}' \
    /etc/nginx/nginx.conf > /tmp/nginx.conf.new && cp /tmp/nginx.conf.new /etc/nginx/nginx.conf
fi
rm -f "$BLOCK"

# --- Server block ---
cat <<'EOF' > /etc/nginx/conf.d/benchmark-site.conf
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log  /var/log/nginx/benchmark-error.log warn;

    limit_req zone=benchmark_limit burst=10;

    location / {
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;

    location = /health {
        access_log off;
        return 200 "ok\n";
    }
}
EOF

# --- Disable default site ---
rm -f /etc/nginx/sites-enabled/default

# --- Test config, then start/reload ---
nginx -t
nginx -s reload 2>/dev/null || nginx

echo "Access log: /var/log/nginx/benchmark-access.log"
curl -sf http://localhost:8080/ && echo "OK: serving on :8080"
SCRIPT
chmod +x /root/setup-nginx-benchmark.sh
echo "=== script saved; verifying idempotency by re-running ==="
/root/setup-nginx-benchmark.sh
